  },
  seeAllText: {
    fontSize: 14,
    color: '#2563EB',
  },
  taskList: {
    marginTop: 16,
    gap: 12,
    paddingHorizontal: 20,
  },
  taskCard: {
    flexDirection: 'row',
    alignItems: 'center',
    borderRadius: 16,
    backgroundColor: '#FFFFFF',
    padding: 16,
  },
  taskCheck: {
    height: 20,
    width: 20,
    borderRadius: 10,
    borderWidth: 2,
    borderColor: '#D1D5DB',
  },
  taskCheckDone: {
    borderColor: '#2563EB',
    backgroundColor: '#2563EB',
  },
  taskBody: {
    marginLeft: 12,
    flex: 1,
  },
  taskTitle: {
    fontSize: 16,
    color: '#111827',
  },
  taskTitleDone: {
    color: '#9CA3AF',
    textDecorationLine: 'line-through',
  },
  taskTime: {
    fontSize: 12,
    color: '#9CA3AF',
  },
});
{{/if}}
